-- que quedan abiertas están en docs/fuentes-bandas.md.
-- Cada salto de línea es un párrafo en la página.
SET NAMES utf8mb4;

UPDATE `bandas` SET `descripcion` = 'Usted Señalemelo es un trío de indie rock de la ciudad de Mendoza. Lo integran Juan Saieg (voz y sintetizadores), Gabriel “Cocó” Orozco (guitarra y voz) y Lucca Beguerie Petrich (batería), que se conocen desde el colegio.
Editó tres discos de estudio: Usted Señalemelo (2015), con la canción “Agua Marfil”; II (2017), con “Big Bang” como primer adelanto; y Tripolar (2023).
Tripolar fue producido por Rafa Arcaute y Nico Cotton, tiene a Gustavo Santaolalla como invitado y fue nominado al Latin Grammy como mejor álbum de pop/rock.
La banda tocó en Lollapalooza Argentina y, en agosto de 2023, en Lollapalooza Chicago, además de hacer giras por Latinoamérica, Estados Unidos y Europa.' WHERE `nombre` = 'Usted Señalemelo';

UPDATE `bandas` SET `descripcion` = 'Mi Amigo Invencible nació en Mendoza en 2007 y hace varios años está radicada en Buenos Aires. La integran Mariano Di Césare (voz y guitarra), Nicolás Voloschin (voz y guitarra), Arturo Martín (batería), Leonardo Gudiño (percusión), Pablo Di Nardo (teclados) y Lucila Pivetta (bajo).
Relatos de un incendio, La Nostalgia Soundsystem (2013) y La danza de los principiantes (2015) le dieron visibilidad nacional e internacional. Del último salió “Máquina del tiempo”, una de sus canciones más escuchadas.
Tres de sus discos fueron nominados a los Premios Gardel: Dutsiland (2019), coproducido con Luke Temple; Isla de oro (2022); y Arco y flecha (2024), producido por Mariano Otero, con Juliana Gattas y Usted Señalemelo como invitados.
Se presentó en festivales como Primavera Sound, Lollapalooza Argentina y Quilmes Rock.' WHERE `nombre` = 'Mi Amigo Invencible';

UPDATE `bandas` SET `descripcion` = 'Pasado Verde es una banda mendocina que empezó a formarse en 2006. Su voz es Exequiel Stocco, único integrante original en la formación publicada en 2019, junto a Joaquín Ferreira Nazar (guitarra y sintetizador), Juan Franco Santillán (bajo y coros), Fabricio Potenzone (guitarra) y Leonardo Lemoli (batería).
Sus discos son Para crecer y olvidar, Fuimos y seremos, Fuego y Flora (2016), Declaración de principios (2020) y La expedición (2023). Empezó cerca del punk-hardcore y con Fuego y Flora giró hacia el indie y el pop rock.
La expedición fue el primero con productores externos: Lucca Beguerie Petrich y Joaquín Guevara.
En 2017 fue la banda de Mendoza más escuchada en Spotify, y en 2019 tocó en el Teatro Griego Frank Romero Day durante la Vendimia. En 2026 preparó un recital en Maipú por los diez años de Fuego y Flora mientras trabajaba en su sexto disco.' WHERE `nombre` = 'Pasado Verde';

UPDATE `bandas` SET `descripcion` = 'Gauchito Club nació en Mendoza en 2015. La integran los hermanos Gabriel Nazar (voz, guitarras y teclados) y Sasha Nazar (voz y bajo), junto a Julián Bermejo (guitarras), Nahuel Quimey Chandía (percusión) y Alejandro Rezk (saxofón y clarinete).
Su identidad combina cumbia, rock, funk, bolero, reggae y otros sonidos latinoamericanos.
Editó tres discos de estudio: Guandanara (2018), El camino de la libertad (2021) y Vulnerable (2024), que incluye “Papito Barloa”, “Primer Recreo” y “Morena Mía”.
Durante la gira de Vulnerable llenó el estadio Obras en Buenos Aires y agotó fechas en España. También pasó por Lollapalooza, Cosquín Rock y Quilmes Rock.' WHERE `nombre` = 'Gauchito Club';

UPDATE `bandas` SET `descripcion` = 'Verona es una banda formada en 2017 y parte de la nueva ola de propuestas alternativas de Mendoza. La integran Leandro Villanueva (guitarra y voz), Federico Calderón (sintetizadores y coros), Martín Villanueva (batería) y Guillermo Martelossi (bajo).
Su sonido es un synth pop con actitud punk y, en palabras de Leandro Villanueva, con mucho new wave y referencias a los años 80 y 90.
A fines de 2021 publicó su primer disco, Verona, adelantado por “Vapor”, “Mantua” y “Alquimia”. Lo grabó en sus casas, lo coprodujo con Gustavo Iglesias (Babasónicos) y lo mezcló en Estudios Juno.' WHERE `nombre` = 'Verona';

UPDATE `bandas` SET `descripcion` = 'Candi Viosch es el nombre artístico de Candela, cantante y compositora nacida en La Plata que eligió Mendoza para vivir y crecer musicalmente.
Estudió música desde chica, a los 15 años pasó a una escuela de música y después siguió Arte Dramático en la Universidad Nacional de Cuyo. Esa formación teatral acompaña su propuesta artística.
Empezó a componer durante la pandemia. A comienzos de 2021 conoció a su productor, Martín Robaldo (MERF), y en abril de ese año dio su primer show.
Su música se mueve en el pop urbano, con boleros y baladas. Su proyecto debut es Agridulce dualidad, adelantado por “Nunca pensé”.' WHERE `nombre` = 'Candi Viosch';

UPDATE `bandas` SET `descripcion` = 'Santo Tabú es un proyecto de rock de Mendoza que comenzó a fines de 2008 como trío: Ivo Procheret (guitarra y voz), Leo Cortés (bajo y coros) y Pablo Peinado (batería).
En agosto de 2009 publicó su primer disco, Santo Tabú, y lo llevó por varias provincias y por Chile, con shows en Valparaíso y Santiago.
Su segundo disco, Cristal Ámbar, salió en 2012: baja la distorsión y suma canciones de tempo medio con arreglos de cuerdas. Lo presentó en el Teatro Independencia.
Tras una estadía en Buenos Aires y una pausa, volvió en 2016 y grabó “Teatro de Amor”, antes de separarse otra vez.
En 2024 retomó los ensayos con Procheret y Cortés junto a David Levy (guitarra y coros) y Nico Di Giorgi (batería). En 2026 trabaja en su tercer álbum.' WHERE `nombre` = 'Santo Tabú';

UPDATE `bandas` SET `descripcion` = 'Chantas es una banda de rocanrol nacida en Mendoza. Se formó cerca de 2004 y tuvo su comienzo formal en 2011.
En 2017 editó su primer disco, Hace tiempo: diez canciones grabadas en Fader Records, presentadas en N8 Estudio con las entradas agotadas.
Después de un recambio de formación en 2019 llegó su segundo disco, Un gesto (2021), con siete canciones grabadas en Estática Records y producción de Didier Turello. Lo presentó en el Teatro Plaza de Godoy Cruz.
En ese momento la integraban Charli Miranda (voz), Jorge Martínez (guitarra), Jona Watkins (bajo) y Maxi “Moja” Murúa (teclados). Compartió fechas con bandas como Pier, Nuestra Raza y La Skandalosa Tripulación.' WHERE `nombre` = 'Chantas';

UPDATE `bandas` SET `descripcion` = 'Brut4l es una banda de hard rock de Mendoza formada a fines de 2012. En su formación de 2020 estaban Leonardo Magri (guitarra y voz), Fernando Mansur (batería) y Mauricio Guiñazú (bajo).
Su primer trabajo fue el EP promocional Impulso (2013), seguido del DVD en vivo 50 años de Amor Brutal (2014), filmado en la Nave Cultural.
Su primer disco es Siervo. Incluye “Lobo”, una canción que se usó en una videocampaña contra la violencia de género y la trata de personas.
En 2020 fue parte del MendoRock virtual, filmado en el Espacio Cultural Julio Le Parc.' WHERE `nombre` = 'Brut4l';

UPDATE `bandas` SET `descripcion` = 'Chancho Va es una banda de rock mendocina formada en 2000. Su sonido mezcla el rock urbano, el alternativo y el hardcore, con letras de contenido social.
Tuvo varias formaciones alrededor de Leandro “Canario” Vilariño (voz y guitarra). En 2025 lo acompañaban Rodrigo Perea (batería), Guillermo Becerra (bajo y coros) y David Nañez (guitarra).
Entre sus trabajos, editados de manera independiente, están Hombre Plastilina (2005), El Mono del Rey (2007), Aun (2011), el EP Nueva Media Hora y Pogo (2019).
En 2004 tocó junto a Motörhead en la Vieja Usina de Córdoba, y pasó por los festivales Cosquín Rock y Quilmes Rock.' WHERE `nombre` = 'Chancho Va';
